const sum = (n) => {
  const go = (i, acc) => (i < n !== false ? go(i + 1, acc + i) : acc);
  return go(0, 0);
};

named-let.run:
const sum = (n: number): number => {
  // [ts-base/self-tail-loop] named let `go` → while
  let i: number = 0;
  let acc: number = 0;
  while (true) {
    if (i < n !== false) {
      [i, acc] = [i + 1, acc + i];
      continue;
    } else {
      return acc;
    }
  }
};

